// 1. Blocking Task (나쁜 예)
function heavy() {
  // 10억 번 루프: 메인 스레드를 완전히 차단함
  for (let i = 0; i < 1000000000; i++) {}
}

// 2. Chunking & Yielding (좋은 예)
let i = 0;
function heavyChunk() {
  // 100만 번만 수행 (Chunk)
  const end = i + 1000000;
  while (i < end) { i++; }

  // "잠깐 쉴게" -> 렌더링 기회 제공 (Yield)
  if (i < 1000000000) {
    setTimeout(heavyChunk, 0);
  }
}
